#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long original = n;
    int digits = 0;
    for (long long t = n; t > 0; t /= 10) {
        digits++;
    }
    long long total = 0;
    while (n > 0) {
        long long digit = n % 10;
        long long power = 1;
        for (int i = 0; i < digits; i++) {
            power *= digit;
        }
        total += power;
        n /= 10;
    }
    cout << (total == original ? "yes" : "no") << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long original = n;
        int digits = 0;
        for (long t = n; t > 0; t /= 10) {
            digits++;
        }
        long total = 0;
        while (n > 0) {
            long digit = n % 10;
            long power = 1;
            for (int i = 0; i < digits; i++) {
                power *= digit;
            }
            total += power;
            n /= 10;
        }
        System.out.println(total == original ? "yes" : "no");
    }
}
